//! Applications test data (.offrails/guides/testing.md#factories-testsappfactoriesrs): valid params
//! through `validate` + `create`, so a test can't build an invalid row. Generated by `cargo offrails generate model applications request:references{request} pitch:text contact:string`.

/// Valid ApplicationParams (unique values numbered), for forms and `application_with`.
pub async fn application_params(
    db: &sea_orm::DatabaseConnection,
    _user: &board::models::User,
) -> board::models::application::ApplicationParams {
    static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(1);
    let n = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let owner = super::user(db, &format!("request-owner-{n}@example.com")).await;
    let request = super::request(db, &owner).await;
    board::models::application::ApplicationParams {
        request_id: request.id.to_string(),
        pitch: format!("Pitch {n}, long enough to read."),
        contact: format!("Contact {n}"),
    }
}

/// A application owned by `user`, through `ApplicationParams::validate` + `application::create`.
pub async fn application(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
) -> board::models::application::Model {
    let params = application_params(db, user).await;
    application_with(db, user, params).await
}

/// A application owned by `user` from these params (they must be valid).
pub async fn application_with(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
    params: board::models::application::ApplicationParams,
) -> board::models::application::Model {
    let new = params.validate().expect("valid application params");
    board::models::application::create(db, user, new)
        .await
        .expect("create application")
}

/// Reads a application back through the entity (tests can't call the model-private `find`).
pub async fn reload_application(
    db: &sea_orm::DatabaseConnection,
    id: i64,
) -> Option<board::models::application::Model> {
    use sea_orm::EntityTrait;
    board::models::application::Entity::find_by_id(id)
        .one(db)
        .await
        .expect("reload application")
}
